CREATE TABLE `sms_collectors` (`id` VARCHAR(191) NOT NULL, `device_name` VARCHAR(191) NOT NULL, `device_identifier` VARCHAR(191) NOT NULL, `api_key_hash` VARCHAR(191) NOT NULL, `phone_number` VARCHAR(191) NOT NULL, `status` ENUM('ONLINE','DEGRADED','OFFLINE','DISABLED') NOT NULL DEFAULT 'OFFLINE', `last_heartbeat_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `sms_collectors_device_identifier_key`(`device_identifier`), INDEX `sms_collectors_status_last_heartbeat_at_idx`(`status`, `last_heartbeat_at`), PRIMARY KEY (`id`));
CREATE TABLE `sms_messages` (`id` VARCHAR(191) NOT NULL, `collector_id` VARCHAR(191) NOT NULL, `message_uid` VARCHAR(191) NOT NULL, `receiver_number` VARCHAR(191) NOT NULL, `sender_number` VARCHAR(191) NOT NULL, `message_text` TEXT NOT NULL, `received_at` DATETIME(3) NOT NULL, `status` ENUM('NEW','MATCHED','UNMATCHED','PROCESSED','IGNORED','DUPLICATE','NEEDS_REVIEW') NOT NULL DEFAULT 'NEW', `matched_application_id` VARCHAR(191) NULL, `processed_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `sms_messages_message_uid_key`(`message_uid`), INDEX `sms_messages_receiver_number_received_at_idx`(`receiver_number`, `received_at`), INDEX `sms_messages_status_received_at_idx`(`status`, `received_at`), PRIMARY KEY (`id`));
CREATE TABLE `otp_matches` (`id` VARCHAR(191) NOT NULL, `sms_message_id` VARCHAR(191) NOT NULL, `application_id` VARCHAR(191) NOT NULL, `automation_job_id` VARCHAR(191) NULL, `encrypted_otp_value` TEXT NOT NULL, `matched_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `consumed_at` DATETIME(3) NULL, `expires_at` DATETIME(3) NOT NULL, UNIQUE INDEX `otp_matches_sms_message_id_key`(`sms_message_id`), INDEX `otp_matches_application_id_expires_at_idx`(`application_id`, `expires_at`), PRIMARY KEY (`id`));
CREATE TABLE `collector_events` (`id` VARCHAR(191) NOT NULL, `collector_id` VARCHAR(191) NOT NULL, `type` VARCHAR(191) NOT NULL, `message` VARCHAR(500) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `collector_events_collector_id_created_at_idx`(`collector_id`, `created_at`), PRIMARY KEY (`id`));
ALTER TABLE `sms_messages` ADD CONSTRAINT `sms_messages_collector_id_fkey` FOREIGN KEY (`collector_id`) REFERENCES `sms_collectors`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `sms_messages` ADD CONSTRAINT `sms_messages_matched_application_id_fkey` FOREIGN KEY (`matched_application_id`) REFERENCES `applications`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `otp_matches` ADD CONSTRAINT `otp_matches_sms_message_id_fkey` FOREIGN KEY (`sms_message_id`) REFERENCES `sms_messages`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `otp_matches` ADD CONSTRAINT `otp_matches_application_id_fkey` FOREIGN KEY (`application_id`) REFERENCES `applications`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `collector_events` ADD CONSTRAINT `collector_events_collector_id_fkey` FOREIGN KEY (`collector_id`) REFERENCES `sms_collectors`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `sms_messages` ADD COLUMN `encrypted_otp_candidate` TEXT NULL;
